class Evaluator:
    def __init__(self, expression):
        self.expression = expression
        self.position = 0
        self.current_char = self.expression[self.position]

    def error(self):
        raise Exception("Invalid syntax")

    def advance(self):
        self.position += 1
        if self.position < len(self.expression):
            self.current_char = self.expression[self.position]
        else:
            self.current_char = None

    def skip_whitespace(self):
        while self.current_char is not None and self.current_char.isspace():
            self.advance()

    def number(self):
        result = ''
        while self.current_char is not None and (
            self.current_char.isdigit() or self.current_char == '.'):
            result += self.current_char
            self.advance()
        return float(result)

    def factor(self):
        if self.current_char == '(':
            self.advance()
            result = self.expr()
            if self.current_char == ')':
                self.advance()
                return result
            else:
                self.error()
        elif self.current_char.isdigit() or self.current_char == '.':
            return self.number()
        else:
            self.error()

    def term(self):
        result = self.factor()
        while self.current_char is not None and self.current_char in ('*', '/'):
            operation = self.current_char
            self.advance()
            if operation == '*':
                result *= self.factor()
            elif operation == '/':
                result /= self.factor()
        return result

    def expr(self):
        result = self.term()
        while self.current_char is not None and self.current_char in ('+', '-'):
            operation = self.current_char
            self.advance()
            if operation == '+':
                result += self.term()
            elif operation == '-':
                result -= self.term()
        return result

