    """Evaluates arithmetic expressions using a recursive descent parser to tokenize and interpret the expression directly, handling operator precedence and parentheses."""

    def parse_expression(index):
        nonlocal expr
        total, index = parse_term(index)

        while index < len(expr):
            if expr[index] == '+':
                index += 1
                term, index = parse_term(index)
                total += term
            elif expr[index] == '-':
                index += 1
                term, index = parse_term(index)
                total -= term
            else:
                break

        return total, index

    def parse_term(index):
        nonlocal expr
        total, index = parse_factor(index)

        while index < len(expr):
            if expr[index] == '*':
                index += 1
                factor, index = parse_factor(index)
                total *= factor
            elif expr[index] == '/':
                index += 1
                factor, index = parse_factor(index)
                total /= factor
            else:
                break

        return total, index

    def parse_factor(index):
        nonlocal expr
        if expr[index] == '(':
            index += 1
            value, index = parse_expression(index)
            index += 1  # skip ')'
            return value, index
        else:
            start = index
            while index < len(expr) and (expr[index].isdigit() or expr[index] == '.'):
                index += 1
            return float(expr[start:index]), index

    index = 0
    result, _ = parse_expression(index)
    return result

